parameters.command:
={{(() => {
  const q = (value) => "'" + String(value ?? "").replace(/'/g, "'\\''") + "'";
  const afterEffectsApp = "Adobe After Effects 2026";
  const stdout = String($("Copy and edit").item.json.stdout ?? "");
  if (stdout.includes("influencer-n8n-result:")) {
    return "echo Already finished on the Mac";
  }
  let progressUrl = "";
  let progressToken = "";
  try {
    const form = $("On form submission").item.json;
    progressUrl = String(form.progressUrl || "");
    progressToken = String(form.progressToken || "");
  } catch (error) {}
  try {
    const hook = $("Influencer webhook").item.json;
    const body = hook.body && typeof hook.body === "object" ? hook.body : hook;
    progressUrl = String(body.progressUrl || progressUrl);
    progressToken = String(body.progressToken || progressToken);
  } catch (error) {}
  const qProgress = (value) => "'" + String(value ?? "").replace(/'/g, "'\\''") + "'";
  const line = stdout.split("\n").reverse().find((row) => row.startsWith("AE_JOB "));
  if (!line) {
    throw new Error("The copy step did not report the new folder.");
  }
  const job = JSON.parse(line.slice("AE_JOB ".length));
  const dest = q(job.destination);
  const appName = q(afterEffectsApp);
  return [
    "bash <<'BASH'",
    "set -euo pipefail",
    "export INFLUENCER_PROGRESS_URL=" + qProgress(progressUrl),
    "export INFLUENCER_PROGRESS_TOKEN=" + qProgress(progressToken),
    "dest=" + dest,
    "app_name=" + appName,
    'if [ ! -d "$dest" ]; then',
    '  echo "Destination folder does not exist: $dest" >&2',
    "  exit 1",
    "fi",
    'app_path="/Applications/Adobe After Effects 2026/Adobe After Effects 2026.app"',
    'if [ ! -d "$app_path" ]; then',
    '  echo "After Effects application not found: $app_path" >&2',
    "  exit 1",
    "fi",
    'if pgrep -x "After Effects" >/dev/null 2>&1; then',
    '  echo "After Effects is already running. Quit it, then run this form again." >&2',
    "  exit 1",
    "fi",
    'dest_real=$(cd "$dest" && pwd -P)',
    'jsx="$dest_real/ae-relink.jsx"',
    'log="$dest_real/ae-launch.log"',
    'result="$dest_real/ae-relink-result.txt"',
    'if [ ! -f "$jsx" ]; then',
    '  echo "JSX file not found: $jsx" >&2',
    "  exit 1",
    "fi",
    'rm -f "$result"',
    'osascript >"$log" 2>&1 <<APPLESCRIPT &',
    'set scriptText to read POSIX file "$jsx" as «class utf8»',
    'tell application "$app_name"',
    '  DoScript scriptText',
    "end tell",
    "APPLESCRIPT",
    "pid=$!",
    "sleep 1",
    'if ! kill -0 "$pid" 2>/dev/null; then',
    '  echo "After Effects did not start. Log: $log" >&2',
    '  cat "$log" >&2',
    "  exit 1",
    "fi",
    'echo "Started After Effects pid $pid"',
    "deadline=$((SECONDS + 180))",
    'while [ ! -s "$result" ]; do',
    '  if [ "$SECONDS" -ge "$deadline" ]; then',
    '    echo "After Effects did not write a relink result. Log: $log" >&2',
    '    if [ -f "$log" ]; then',
    '      tail -n 40 "$log" >&2',
    "    fi",
    "    exit 1",
    "  fi",
    "  sleep 1",
    "done",
    'first=$(head -n 1 "$result" | tr -d "\\r" || true)',
    'prefix="Saved "',
    'if [ "${first#"$prefix"}" = "$first" ]; then',
    '  echo "After Effects did not relink the project." >&2',
    '  cat "$result" >&2',
    "  exit 1",
    "fi",
    'echo "Folder: $dest_real"',
    'echo "Result:"',
    'cat "$result"',
    "export dest_real",
    "python3 - <<'PY' || true",
    "import json, os, urllib.request",
    "url = os.environ.get('INFLUENCER_PROGRESS_URL', '').strip()",
    "token = os.environ.get('INFLUENCER_PROGRESS_TOKEN', '').strip()",
    "dest = os.environ.get('dest_real', '').strip()",
    "line = 'influencer-n8n-result: ' + dest if dest else ''",
    "if url and line:",
    "    data = json.dumps({'line': line}).encode()",
    "    req = urllib.request.Request(url, data=data, method='POST', headers={'Content-Type': 'application/json', 'X-Progress-Token': token})",
    "    urllib.request.urlopen(req, timeout=5).read()",
    "PY",
    "BASH",
  ].join("\n");
})()}}
